const body = $input.first().json;
const alerts = body.alerts || [];
const alert = alerts[0] || {};
const labels = alert.labels || {};
const values = alert.values || {};
const desc = (alert.annotations && (alert.annotations.description || alert.annotations.summary) || '').slice(0, 600);
const durationMs = values.A || values.query_duration_ms || 0;

return [{
  json: {
    alertName: labels.alertname || 'Slow Query',
    instance: labels.instance || 'pocat-db',
    durationMs: durationMs,
    description: desc,
    startTime: alert.startsAt || new Date().toISOString(),
    generatorURL: alert.generatorURL || '',
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 300,
      messages: [
        {
          role: 'system',
          content: 'POCAT 데이터베이스 슬로우 쿼리 분석 AI입니다. 한국어로 3줄 이내 답변하세요.'
        },
        {
          role: 'user',
          content: '슬로우 쿼리 감지\n인스턴스: ' + (labels.instance || '') + '\n소요 시간: ' + durationMs + 'ms\n내용: ' + desc + '\n\n쿼리 최적화 방법, 인덱스 추가 필요 여부, 즉시 조치를 각 1줄로 답변하세요.'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const analysis = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '분석 실패';
const prev = $('Parse Query Alert').first().json;

return [{
  json: {
    slackPayload: {
      text: '⏱️ *[슬로우 쿼리] ' + prev.instance + ' — ' + prev.durationMs + 'ms*',
      attachments: [{
        color: 'warning',
        fields: [
          { title: '인스턴스', value: prev.instance || '-', short: true },
          { title: '소요 시간', value: prev.durationMs + 'ms', short: true },
          { title: '내용', value: prev.description || '-', short: false },
          { title: 'AI 최적화 제안', value: analysis, short: false }
        ],
        footer: 'POCAT Monitoring | ' + prev.startTime
      }]
    }
  }
}];
